import axios from 'axios';
const BASE_URL = 'http://localhost:9000';
const client = axios.create({
  baseURL: BASE_URL,
  headers: {
    'Content-Type': 'application/json'
  }
});
export const authApi = {
  // Kiểm tra đăng nhập dựa trên bảng accounts
  login: (username, password) => client.get(`/accounts`, {
    params: {
      username,
      password
    }
  }).then(r => r.data.length > 0 ? r.data[0] : null),
  findByUsername: username => client.get(`/accounts`, {
    params: {
      username
    }
  }).then(r => r.data[0] || null),
  register: user => client.post('/accounts', {
    ...user,
    role: 'Student',
    status: 'active'
  }).then(r => r.data),
  getAllUsers: () => client.get('/accounts').then(r => r.data),
  createUser: user => client.post('/accounts', user).then(r => r.data),
  updateUser: (id, user) => client.put(`/accounts/${id}`, user).then(r => r.data),
  deleteUser: id => client.delete(`/accounts/${id}`)
};
